export const getDisplayStateResponseDisplaysItemExpiresInMsMin = 0;

export const getDisplayStateResponseDisplaysItemGroupMin = 0;

export const getDisplayStateResponseDisplaysItemIdentitySlotMin = 0;

export const getDisplayStateResponseDisplaysItemSessionsMin = 0;

export const getDisplayStateResponseDisplaysItemSlotMin = 0;



