/**
 * Arms a new performance-stats capture. Idempotent: if a capture is already running this returns
 * the current status unchanged. While armed, the streaming loops emit aggregated samples (~ every
 * 1–2 s) into the in-progress capture, readable live via `GET /stats/capture/live`.
 * @summary Start a stats capture
 */
export const statsCaptureStartResponseElapsedMsMin = 0;

export const statsCaptureStartResponseSampleCountMin = 0;

export const statsCaptureStartResponseStartedUnixMsMin = 0;



export const StatsCaptureStartResponse = S.Struct({
  "armed": S.Boolean.annotations({ description: 'Capture currently running.' }),
  "elapsed_ms": S.Number.pipe(S.greaterThanOrEqualTo(statsCaptureStartResponseElapsedMsMin)).annotations({ description: 'Host-measured elapsed time of the in-progress capture, in ms (`0` if idle). Computed from the\nhost\'s MONOTONIC clock, so a console can show elapsed time without subtracting `started_unix_ms`\nfrom its own (possibly skewed) wall clock.' }),
  "kind": S.String.annotations({ description: 'Path of the in-progress capture (`\"\"` if idle).' }),
  "sample_count": S.Number.pipe(S.greaterThanOrEqualTo(statsCaptureStartResponseSampleCountMin)).annotations({ description: 'Samples in the in-progress capture.' }),
  "started_unix_ms": S.Number.pipe(S.greaterThanOrEqualTo(statsCaptureStartResponseStartedUnixMsMin)).annotations({ description: 'Unix start time of the in-progress capture (`0` if idle).' })
}).annotations({ description: 'Snapshot of the in-progress capture for the management API.' })


