/**
 * @summary Live host status
 */
export const getStatusResponseActiveSessionsMin = 0;

export const getStatusResponsePairedClientsMin = 0;

export const getStatusResponseSessionTwoFpsMin = 0;

export const getStatusResponseSessionTwoHeightMin = 0;

export const getStatusResponseSessionTwoWidthMin = 0;

export const getStatusResponseStreamTwoBitrateKbpsMin = 0;

export const getStatusResponseStreamTwoFpsMin = 0;

export const getStatusResponseStreamTwoHeightMin = 0;

export const getStatusResponseStreamTwoMinFecMin = 0;

export const getStatusResponseStreamTwoPacketSizeMin = 0;

export const getStatusResponseStreamTwoWidthMin = 0;



export const GetStatusResponse = S.Struct({
  "active_sessions": S.Number.pipe(S.greaterThanOrEqualTo(getStatusResponseActiveSessionsMin)).annotations({ description: 'Number of live streaming sessions across BOTH planes (GameStream + native punktfunk\/1). The\nnative server admits concurrent sessions, so this can exceed 1; `session`\/`stream` below\ndescribe a single representative session for the detail card.' }),
  "audio_streaming": S.Boolean.annotations({ description: 'True while the audio stream thread is running.' }),
  "paired_clients": S.Number.pipe(S.greaterThanOrEqualTo(getStatusResponsePairedClientsMin)).annotations({ description: 'Number of pinned (paired) client certificates.' }),
  "pin_pending": S.Boolean.annotations({ description: 'True while a pairing handshake is parked waiting for the user\'s PIN\n(submit it via `POST \/api\/v1\/pair\/pin`).' }),
  "session": S.optional(S.Union(S.Null, S.Struct({
  "fps": S.Number.pipe(S.greaterThanOrEqualTo(getStatusResponseSessionTwoFpsMin)),
  "height": S.Number.pipe(S.greaterThanOrEqualTo(getStatusResponseSessionTwoHeightMin)),
  "width": S.Number.pipe(S.greaterThanOrEqualTo(getStatusResponseSessionTwoWidthMin))
}).annotations({ description: 'A representative active session. GameStream\'s launch (Moonlight `\/launch`) when present, else\nthe first live native session. `null` when nothing is streaming.' }))),
  "stream": S.optional(S.Union(S.Null, S.Struct({
  "bitrate_kbps": S.Number.pipe(S.greaterThanOrEqualTo(getStatusResponseStreamTwoBitrateKbpsMin)),
  "codec": S.Literal('h264', 'hevc', 'av1', 'pyrowave').annotations({ description: 'Video codec identifier. The wire token matches the codec\'s canonical name used across the\nstack (SDP\/GameStream advertisement, the stats-capture `CaptureMeta.codec`, and the encoder\'s\n[`Codec::label`]) — notably `H.265` serializes as `\"hevc\"`, not `\"h265\"`, so the same codec\nreads identically on every console page.' }),
  "fps": S.Number.pipe(S.greaterThanOrEqualTo(getStatusResponseStreamTwoFpsMin)),
  "height": S.Number.pipe(S.greaterThanOrEqualTo(getStatusResponseStreamTwoHeightMin)),
  "min_fec": S.Number.pipe(S.greaterThanOrEqualTo(getStatusResponseStreamTwoMinFecMin)).annotations({ description: 'Client\'s parity floor per FEC block (`minRequiredFecPackets`).' }),
  "packet_size": S.Number.pipe(S.greaterThanOrEqualTo(getStatusResponseStreamTwoPacketSizeMin)).annotations({ description: 'Video payload size per packet (bytes).' }),
  "width": S.Number.pipe(S.greaterThanOrEqualTo(getStatusResponseStreamTwoWidthMin))
}).annotations({ description: 'The active stream\'s parameters — RTSP-negotiated for GameStream, or the live native session\'s\nmode\/codec\/bitrate. `null` when nothing is streaming.' }))),
  "video_streaming": S.Boolean.annotations({ description: 'True while the video stream thread is running.' })
}).annotations({ description: 'Live host status (changes as clients launch\/end sessions).' })
